            Assert.DoesNotContain("example.com", result.Content.ToString());
            Assert.DoesNotContain("skip", result.Content.ToString());
            Assert.DoesNotContain("Skip", result.Content.ToString());

        }

        [Fact]
        public void Test_VisitorSkipStrong()
        {
            // Visitor skips bold/strong elements
            var _visitor_visitor_skip_strong = new VisitorSkipStrongVisitor();
            var options = new ConversionOptions { Visitor = _visitor_visitor_skip_strong };
            var result = HtmlToMarkdownConverter.Convert("<p>Normal <strong>bold text</strong> normal</p>", options);
            Assert.DoesNotContain("bold text", result.Content.ToString());
            Assert.Contains("Normal", result.Content.ToString());
            Assert.DoesNotContain("skip", result.Content.ToString());
            Assert.DoesNotContain("Skip", result.Content.ToString());

        }

        [Fact]
