        [Fact]
        public void Test_VisitorVideoCustom()
        {
            // Visitor replaces video with custom link
            var _visitor_visitor_video_custom = new VisitorVideoCustomVisitor();
            var options = new ConversionOptions { Visitor = _visitor_visitor_video_custom };
            var result = HtmlToMarkdownConverter.Convert("<p>Watch our tutorial:</p><video src=\"tutorial.mp4\" width=\"320\" height=\"240\" controls></video><p>Great content!</p>", options);
            Assert.Contains("[VIDEO: tutorial.mp4]", result.Content.ToString());
            Assert.Contains("Watch our tutorial:", result.Content.ToString());
            Assert.Contains("Great content!", result.Content.ToString());

        }

        [Fact]
